// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: de outubro a dezembro, 1/10 do ano corrente; de janeiro a setembro, 1/10 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08. Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo".
  cicloInicio: { mes: 10, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra }. Blocos de 500 (VALUES aceita até 1000 linhas).
const sqlCadastros = (linhas) => {
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (Tipo, Id, Nome, Extra) VALUES (origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "Preparar consulta" (workflow CNN Painel - Leitura). Lê body.action, valida os parâmetros e monta o SQL.
// Cada SELECT leva a coluna _secao: o nó SQL junta os resultados num só array, e a resposta separa por ela.
const unwrap = (valor) => {
  if (typeof valor === 'string') {
    try {
      return JSON.parse(valor);
    } catch (erro) {
      return {};
    }
  }

  return valor && typeof valor === 'object' && !Array.isArray(valor) ? valor : {};
};

const item = unwrap($input.first().json);
const body = { ...item, ...unwrap(item.body) };
const action = String(body.action || '').trim();

const erro = (statusCode, mensagem) => [{
  json: { action: 'error', statusCode, response: { error: mensagem } }
}];
const safeDate = (valor) => (/^\d{4}-\d{2}-\d{2}$/.test(String(valor || '')) ? String(valor) : '');
const escolha = (valor, permitidos) => (permitidos.includes(String(valor || '')) ? String(valor) : '');

const inicio = inicioCiclo();
const hoje = hojeSp();
const dias = (coluna) => sqlDiasCase(coluna);

// Nomes gravados pelo bloqueio (01:00) a partir das listas da API. Executor: Id = idpessoa da agenda.
const nomeCadastro = (tipo, coluna) =>
  `(SELECT TOP (1) cad.Nome FROM dbo.CtlCnnCadastro cad WHERE cad.Tipo = N'${tipo}' AND cad.Id = ${coluna})`;
const profissionalDe = (alias) => `COALESCE(${nomeCadastro('EXECUTOR', `${alias}.IdPessoaExecutor`)}, ${alias}.NomeExecutor)`;
// Procedimentos da falta numa string ("Retorno, Exame"). FOR XML PATH funciona em qualquer versão (STRING_AGG só a partir de 2017).
const procedimentosDe = (colunaAgenda) => `STUFF((
        SELECT N', ' + ISNULL(fp.NomeProcedimento, N'Procedimento ' + CAST(fp.IdTipoProcedimento AS nvarchar(20)))
        FROM dbo.CtlCnnFaltaProcedimento fp
        WHERE fp.IdAgenda = ${colunaAgenda}
        ORDER BY fp.NomeProcedimento
        FOR XML PATH(''), TYPE
    ).value('.', 'nvarchar(max)'), 1, 2, N'')`;
const camposAgenda = (alias) => `${profissionalDe(alias)} AS Profissional,
    ${nomeCadastro('TIPO_CONSULTA', `${alias}.IdTipoConsulta`)} AS TipoConsulta,
    ${nomeCadastro('ROTULO', `${alias}.IdRotulo`)} AS Rotulo,
    ${procedimentosDe(`${alias}.IdAgenda`)} AS Procedimentos`;
const cabecalho = `USE INTEGRACAO;
SET NOCOUNT ON;
DECLARE @inicio DATE = ${sqlDate(inicio)};
DECLARE @hoje DATE = ${sqlDate(hoje)};`;

if (action === 'pacientes') {
  const query = `${cabecalho}
DECLARE @inicioMes DATE = DATEFROMPARTS(YEAR(@hoje), MONTH(@hoje), 1);

;WITH Alvo AS (
    SELECT IdPaciente FROM dbo.CtlCnnFaltaPaciente WHERE DataFalta >= @inicio
    UNION
    SELECT IdPaciente FROM dbo.CtlCnnControlePaciente WHERE Situacao = N'BLOQUEADO'
),
Faltas AS (
    SELECT
        f.IdPaciente,
        f.IdAgenda,
        f.NomePaciente,
        f.DataFalta,
        f.NumeroFalta,
        f.NomeExecutor,
        f.IdPessoaExecutor,
        f.IdTipoConsulta,
        f.IdRotulo,
        ROW_NUMBER() OVER (
            PARTITION BY f.IdPaciente
            ORDER BY CASE WHEN f.DataFalta >= @inicio THEN 0 ELSE 1 END, f.NumeroFalta DESC, f.DataFalta DESC, f.IdAgenda DESC
        ) AS Ordem,
        SUM(CASE WHEN f.DataFalta >= @inicio THEN 1 ELSE 0 END) OVER (PARTITION BY f.IdPaciente) AS FaltasCiclo,
        COUNT(*) OVER (PARTITION BY f.IdPaciente) AS FaltasTotal
    FROM dbo.CtlCnnFaltaPaciente f
    INNER JOIN Alvo a
        ON a.IdPaciente = f.IdPaciente
)
SELECT
    N'paciente' AS _secao,
    v.IdPaciente,
    v.NomePaciente,
    v.IdAgenda,
    CONVERT(char(10), v.DataFalta, 23) AS DataFalta,
    v.NumeroFalta,
    ${camposAgenda('v')},
    v.FaltasCiclo,
    v.FaltasTotal,
    ${dias('v.NumeroFalta')} AS DiasBloqueio,
    CONVERT(char(10), DATEADD(DAY, ${dias('v.NumeroFalta')}, v.DataFalta), 23) AS DataFimBloqueio,
    c.Situacao,
    c.IdAgendaReferencia,
    c.UltimaAcao,
    c.OrigemUltimaAcao,
    c.UltimaAcaoPor,
    c.UltimaAcaoEm,
    s.Id AS SolicitacaoId,
    s.Status AS SolicitacaoStatus,
    s.IdAgendaReferencia AS SolicitacaoIdAgenda,
    s.SolicitadoPor AS SolicitacaoPor,
    s.SolicitadoEm AS SolicitacaoEm
FROM Faltas v
LEFT JOIN dbo.CtlCnnControlePaciente c
    ON c.IdPaciente = v.IdPaciente
LEFT JOIN dbo.CtlCnnSolicitacao s
    ON s.IdPaciente = v.IdPaciente
   AND s.Status IN (N'PENDENTE', N'APROVADA')
WHERE v.Ordem = 1;

SELECT
    N'totais' AS _secao,
    (SELECT COUNT(*) FROM dbo.CtlCnnFaltaPaciente WHERE DataFalta >= @inicio) AS FaltasCiclo,
    (SELECT COUNT(*) FROM dbo.CtlCnnFaltaPaciente WHERE DataFalta >= @inicioMes) AS FaltasMes,
    (SELECT MAX(DataColeta) FROM dbo.CtlCnnFaltaPaciente) AS UltimaColeta,
    (SELECT MAX(CriadoEm) FROM dbo.CtlCnnAcaoPaciente WHERE Origem = N'AUTOMATICO' AND Acao = N'BLOQUEIO') AS UltimoBloqueioAutomatico,
    (SELECT MAX(CriadoEm) FROM dbo.CtlCnnAcaoPaciente WHERE Origem = N'AUTOMATICO' AND Acao = N'LIBERACAO') AS UltimaLiberacaoAutomatica,
    (SELECT COUNT(*) FROM dbo.CtlCnnControlePaciente) AS LinhasControle,
    (SELECT COUNT(*) FROM dbo.CtlCnnSolicitacao WHERE Status = N'PENDENTE') AS SolicitacoesPendentes,
    (SELECT COUNT(*) FROM dbo.CtlCnnSolicitacao WHERE Status = N'APROVADA') AS SolicitacoesAprovadas;`;

  return [{ json: { action, query, inicio, hoje } }];
}

if (action === 'paciente') {
  const id = Number(body.id);
  if (!Number.isSafeInteger(id) || id <= 0) {
    return erro(400, 'Paciente inválido.');
  }

  const query = `${cabecalho}
DECLARE @id BIGINT = ${sqlN(id)};

SELECT
    N'falta' AS _secao,
    IdAgenda,
    NomePaciente,
    CpfCnpj,
    CONVERT(char(10), DataFalta, 23) AS DataFalta,
    CONVERT(char(5), HoraInicio, 108) AS HoraInicio,
    NumeroFalta,
    ${camposAgenda('f')},
    TipoExecutor,
    StatusAgenda,
    DataColeta
FROM dbo.CtlCnnFaltaPaciente f
WHERE IdPaciente = @id
ORDER BY DataFalta DESC, IdAgenda DESC;

SELECT TOP (200)
    N'acao' AS _secao,
    Id,
    Acao,
    Origem,
    Usuario,
    Motivo,
    IdAgendaReferencia,
    NumeroFalta,
    CONVERT(char(10), DataFimBloqueio, 23) AS DataFimBloqueio,
    Antecipada,
    AtivoAntes,
    Sucesso,
    HttpStatus,
    RespostaApi,
    IdSolicitacao,
    CriadoEm
FROM dbo.CtlCnnAcaoPaciente
WHERE IdPaciente = @id
ORDER BY CriadoEm DESC, Id DESC;

SELECT TOP (50)
    N'solicitacao' AS _secao,
    Id,
    IdAgendaReferencia,
    NumeroFalta,
    Motivo,
    SolicitadoPor,
    SolicitadoEm,
    Status,
    DecididoPor,
    DecididoEm,
    MotivoDecisao,
    LiberadoPor,
    LiberadoEm
FROM dbo.CtlCnnSolicitacao
WHERE IdPaciente = @id
ORDER BY SolicitadoEm DESC, Id DESC;

SELECT
    N'controle' AS _secao,
    Situacao,
    IdAgendaReferencia,
    NumeroFalta,
    CONVERT(char(10), DataFimBloqueio, 23) AS DataFimBloqueio,
    UltimaAcao,
