  const ms = Date.parse(`${ate}T00:00:00Z`) - Date.parse(`${de}T00:00:00Z`);
  const tamanho = Math.round(ms / 86_400_000) + 1;
  return { de: somarDias(de, -tamanho), ate: somarDias(de, -1) };
};

