// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: de outubro a dezembro, 1/10 do ano corrente; de janeiro a setembro, 1/10 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08. Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo".
  cicloInicio: { mes: 10, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra }. Blocos de 500 (VALUES aceita até 1000 linhas).
const sqlCadastros = (linhas) => {
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (Tipo, Id, Nome, Extra) VALUES (origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "Montar resposta" (workflow CNN Painel - Leitura). Separa as linhas por _secao e devolve { statusCode, response }.
// Dado sensível (CPF, e-mail, telefone) não sai daqui: o CPF vai mascarado, o resto nem é consultado.
const meta = $('Preparar consulta').first().json;

if (meta.action === 'error') {
  return [{ json: { statusCode: meta.statusCode || 400, response: meta.response || { error: 'Requisição inválida.' } } }];
}

const sqlItens = $('Consultar').all();
const falha = erroSql(sqlItens);
if (falha) {
  return [{ json: { statusCode: 502, response: { error: `Falha na consulta ao banco: ${String(falha).slice(0, 300)}` } } }];
}

const porSecao = {};
for (const linha of linhasSql(sqlItens)) {
  const secao = linha._secao;
  if (!secao) {
    continue;
  }
  const { _secao, ...resto } = linha;
  (porSecao[secao] ||= []).push(resto);
}

const secao = (nome) => porSecao[nome] || [];
const num = (valor) => Number(valor || 0);
const bool = (valor) => valor === true || valor === 1 || valor === '1';
const iso = (valor) => {
  if (!valor) return null;
  const data = valor instanceof Date ? valor : new Date(String(valor).includes('T') || String(valor).endsWith('Z') ? valor : `${String(valor).replace(' ', 'T')}Z`);
  return Number.isNaN(data.getTime()) ? String(valor) : data.toISOString();
};
// Profissional, tipo de consulta, rótulo e procedimentos da falta (nomes de CtlCnnCadastro / CtlCnnFaltaProcedimento).
const agendaDe = (linha) => ({
  profissional: linha.Profissional || linha.NomeExecutor || null,
  tipoConsulta: linha.TipoConsulta || null,
  rotulo: linha.Rotulo || null,
  procedimentos: linha.Procedimentos || null
});
const ok = (response) => [{ json: { statusCode: 200, response: { asOf: new Date().toISOString(), ...response } } }];

const mascararCpf = (valor) => {
  const digitos = String(valor || '').replace(/\D/g, '');
  if (digitos.length === 11) return `***.${digitos.slice(3, 6)}.${digitos.slice(6, 9)}-**`;
  if (digitos.length === 14) return `**.${digitos.slice(2, 5)}.${digitos.slice(5, 8)}/****-**`;
  return digitos ? '***' : null;
};

// Situação do paciente: a tabela de controle vale enquanto aponta para a falta vigente.
// Sem registro para a falta vigente: com o prazo correndo, ninguém confirmou o bloqueio no CNN -> PENDENTE
// ("Aguardando bloqueio"); com o prazo já cumprido, o bloqueio das 01:00 não bloqueia mais -> CUMPRIDO
// (status "liberado": o paciente pode agendar).
const situacaoDe = (vigente, controle) => {
  const controleVale = controle?.Situacao && String(controle.IdAgendaReferencia ?? '') === String(vigente.IdAgenda ?? '');
  const prazoCorrendo = Boolean(vigente.DataFimBloqueio) && vigente.DataFimBloqueio >= meta.hoje;

  if (!controleVale) {
    return prazoCorrendo
      ? { situacao: 'PENDENTE', status: 'pendente', controleVale }
      : { situacao: 'CUMPRIDO', status: 'liberado', controleVale };
  }

  if (controle.Situacao === 'LIBERADO') {
    return { situacao: 'LIBERADO', status: prazoCorrendo ? 'liberado_antecipado' : 'liberado', controleVale };
  }
  return { situacao: 'BLOQUEADO', status: prazoCorrendo ? 'bloqueado' : 'apto', controleVale };
};

if (meta.action === 'pacientes') {
  const items = secao('paciente').map((linha) => {
    const { situacao, status, controleVale } = situacaoDe(linha, linha);
    return {
      idPaciente: num(linha.IdPaciente),
      nome: linha.NomePaciente || null,
      idAgenda: linha.IdAgenda,
      dataFalta: dataIso(linha.DataFalta),
      numeroFalta: num(linha.NumeroFalta),
      ...agendaDe(linha),
      faltasCiclo: num(linha.FaltasCiclo),
      faltasTotal: num(linha.FaltasTotal),
      diasBloqueio: num(linha.DiasBloqueio),
      dataFimBloqueio: dataIso(linha.DataFimBloqueio),
      foraDoCiclo: dataIso(linha.DataFalta) < meta.inicio,
      situacao,
      status,
      ultimaAcao: linha.UltimaAcao
        ? {
            acao: linha.UltimaAcao,
            origem: linha.OrigemUltimaAcao,
            usuario: linha.UltimaAcaoPor,
            em: iso(linha.UltimaAcaoEm),
            vigente: controleVale
          }
        : null,
      // Solicitação de desbloqueio aberta (pendente ou aprovada). "valida": é da falta vigente de agora.
      solicitacao: linha.SolicitacaoId
        ? {
            id: num(linha.SolicitacaoId),
            status: linha.SolicitacaoStatus,
            solicitadoPor: linha.SolicitacaoPor || null,
            em: iso(linha.SolicitacaoEm),
            valida: String(linha.SolicitacaoIdAgenda ?? '') === String(linha.IdAgenda ?? '')
          }
        : null
    };
  });

  const contar = (filtro) => items.filter(filtro).length;
  const totais = secao('totais')[0] || {};

  return ok({
    ciclo: { inicio: meta.inicio, hoje: meta.hoje },
    resumo: {
      pendentes: contar((item) => item.status === 'pendente'),
      bloqueados: contar((item) => item.status === 'bloqueado'),
      aptos: contar((item) => item.status === 'apto'),
      liberadosAntecipados: contar((item) => item.status === 'liberado_antecipado'),
      liberados: contar((item) => item.status === 'liberado'),
      pacientesCiclo: contar((item) => item.faltasCiclo > 0),
      porFaltas: {
        1: contar((item) => item.faltasCiclo === 1),
        2: contar((item) => item.faltasCiclo === 2),
        3: contar((item) => item.faltasCiclo >= 3)
      },
      faltasCiclo: num(totais.FaltasCiclo),
      faltasMes: num(totais.FaltasMes),
      ultimaColeta: iso(totais.UltimaColeta),
      ultimoBloqueioAutomatico: iso(totais.UltimoBloqueioAutomatico),
      controleCarregado: num(totais.LinhasControle) > 0,
      solicitacoesPendentes: num(totais.SolicitacoesPendentes),
      solicitacoesAprovadas: num(totais.SolicitacoesAprovadas)
    },
    total: items.length,
    items
  });
}

if (meta.action === 'paciente') {
  const faltas = secao('falta');
  const controle = secao('controle')[0] || null;

  if (!faltas.length && !controle) {
    return [{ json: { statusCode: 404, response: { error: 'Paciente sem faltas registradas.' } } }];
  }

  const noCiclo = faltas.filter((falta) => dataIso(falta.DataFalta) >= meta.inicio);
  const candidatas = noCiclo.length ? noCiclo : faltas;
  const vigenteLinha = [...candidatas].sort((a, b) =>
    num(b.NumeroFalta) - num(a.NumeroFalta) || String(b.DataFalta).localeCompare(String(a.DataFalta)) || num(b.IdAgenda) - num(a.IdAgenda)
  )[0] || null;

  let vigente = null;
  if (vigenteLinha) {
    const diasBloqueio = diasPorFalta(num(vigenteLinha.NumeroFalta));
    const base = {
      IdAgenda: vigenteLinha.IdAgenda,
      DataFimBloqueio: somarDias(dataIso(vigenteLinha.DataFalta), diasBloqueio)
    };
    const { situacao, status } = situacaoDe(base, controle);
    vigente = {
      idAgenda: vigenteLinha.IdAgenda,
      dataFalta: dataIso(vigenteLinha.DataFalta),
      numeroFalta: num(vigenteLinha.NumeroFalta),
      diasBloqueio,
      dataFimBloqueio: base.DataFimBloqueio,
      ...agendaDe(vigenteLinha),
      noCiclo: noCiclo.length > 0,
      situacao,
      status
    };
  }

  let cnn = { consultado: false, ativo: null, erro: null };
  try {
    const resposta = lerRespostaHttp($('GET paciente CNN').first().json);
    const body = resposta.body && typeof resposta.body === 'object' ? resposta.body : {};
    cnn = resposta.ok && body.id != null
      ? { consultado: true, ativo: typeof body.ativo === 'boolean' ? body.ativo : null, erro: null }
      : { consultado: true, ativo: null, erro: resposta.statusCode ? `HTTP ${resposta.statusCode}` : resposta.erro || 'sem resposta' };
  } catch (erro) {
    cnn = { consultado: false, ativo: null, erro: 'GET não executado' };
  }

  const primeira = faltas.find((falta) => falta.NomePaciente) || faltas[0] || {};

  return ok({
    idPaciente: meta.id,
    nome: primeira.NomePaciente || null,
    cpf: mascararCpf(faltas.find((falta) => falta.CpfCnpj)?.CpfCnpj),
    ciclo: { inicio: meta.inicio, hoje: meta.hoje },
    cnn,
    vigente,
    controle: controle
      ? {
          situacao: controle.Situacao,
          idAgendaReferencia: controle.IdAgendaReferencia,
          numeroFalta: controle.NumeroFalta,
          dataFimBloqueio: dataIso(controle.DataFimBloqueio),
          ultimaAcao: controle.UltimaAcao,
          origem: controle.OrigemUltimaAcao,
          usuario: controle.UltimaAcaoPor,
          motivo: controle.MotivoUltimaAcao,
          em: iso(controle.UltimaAcaoEm)
        }
      : null,
    faltas: faltas.map((falta) => ({
      idAgenda: falta.IdAgenda,
      dataFalta: dataIso(falta.DataFalta),
      horaInicio: falta.HoraInicio || null,
      numeroFalta: num(falta.NumeroFalta),
      ...agendaDe(falta),
      tipoProfissional: falta.TipoExecutor || null,
      noCiclo: dataIso(falta.DataFalta) >= meta.inicio,
      coletadaEm: iso(falta.DataColeta)
    })),
    acoes: secao('acao').map((acao) => ({
      id: acao.Id,
      acao: acao.Acao,
      origem: acao.Origem,
      usuario: acao.Usuario,
      motivo: acao.Motivo,
      idAgenda: acao.IdAgendaReferencia,
      numeroFalta: acao.NumeroFalta,
      dataFimBloqueio: dataIso(acao.DataFimBloqueio),
      antecipada: bool(acao.Antecipada),
      ativoAntes: acao.AtivoAntes === null || acao.AtivoAntes === undefined ? null : bool(acao.AtivoAntes),
      sucesso: bool(acao.Sucesso),
      httpStatus: acao.HttpStatus,
      respostaApi: acao.RespostaApi,
      idSolicitacao: acao.IdSolicitacao ?? null,
      em: iso(acao.CriadoEm)
    })),
    solicitacoes: secao('solicitacao').map((s) => ({
      id: num(s.Id),
      idAgenda: s.IdAgendaReferencia,
      numeroFalta: num(s.NumeroFalta),
      motivo: s.Motivo || '',
      solicitadoPor: s.SolicitadoPor || null,
      solicitadoEm: iso(s.SolicitadoEm),
      status: s.Status,
      decididoPor: s.DecididoPor || null,
      decididoEm: iso(s.DecididoEm),
      motivoDecisao: s.MotivoDecisao || null,
      liberadoPor: s.LiberadoPor || null,
      liberadoEm: iso(s.LiberadoEm),
      valida: vigente ? String(s.IdAgendaReferencia ?? '') === String(vigente.idAgenda ?? '') : false
    }))
  });
}

if (meta.action === 'faltas') {
  const total = secao('total')[0] || {};
  const linhas = secao('linha');
  const limite = 5000;
  const porNome = (nome) => secao(nome).map((linha) => ({ nome: linha.Nome, faltas: num(linha.Faltas), pacientes: num(linha.Pacientes) }));

  return ok({
    periodo: { de: meta.de, ate: meta.ate, inicioCiclo: meta.inicio },
    total: { faltas: num(total.Faltas), pacientes: num(total.Pacientes), comProcedimento: num(total.ComProcedimento) },
    porMes: secao('mes')
      .map((linha) => ({ mes: linha.Mes, faltas: num(linha.Faltas), pacientes: num(linha.Pacientes) }))
      .sort((a, b) => a.mes.localeCompare(b.mes)),
    porDiaSemana: secao('diaSemana')
      .map((linha) => ({ dia: num(linha.DiaSemana), faltas: num(linha.Faltas) }))
      .sort((a, b) => a.dia - b.dia),
    porProfissional: secao('profissional').map((linha) => ({
      profissional: linha.Profissional,
      faltas: num(linha.Faltas),
      pacientes: num(linha.Pacientes)
    })),
    porTipoConsulta: porNome('tipoConsulta'),
    porProcedimento: porNome('procedimento'),
    porRotulo: porNome('rotulo'),
    porPeriodo: secao('periodo')
      .sort((a, b) => num(a.Ordem) - num(b.Ordem))
      .map((linha) => ({ periodo: linha.Periodo, faltas: num(linha.Faltas), pacientes: num(linha.Pacientes) })),
    reincidencia: secao('reincidencia')
      .map((linha) => ({ quantidade: num(linha.Quantidade), pacientes: num(linha.Pacientes) }))
      .sort((a, b) => a.quantidade - b.quantidade),
    maiorFaltaRegra,
    reincidentes: secao('reincidente').map((linha) => ({
      idPaciente: num(linha.IdPaciente),
      nome: linha.NomePaciente || null,
      faltas: num(linha.Faltas),
      ultimaFalta: dataIso(linha.UltimaFalta)
    })),
    truncado: linhas.length > limite,
    linhas: linhas.slice(0, limite).map((linha) => ({
      idAgenda: linha.IdAgenda,
      idPaciente: num(linha.IdPaciente),
      nome: linha.NomePaciente || null,
      dataFalta: dataIso(linha.DataFalta),
      horaInicio: linha.HoraInicio || null,
      numeroFalta: num(linha.NumeroFalta),
      ...agendaDe(linha)
    }))
  });
}

if (meta.action === 'dashboard') {
  const anterior = secao('anterior')[0] || {};
  const acao = secao('acaoResumo')[0] || {};
  const tempo = secao('solTempo')[0] || {};
  const media = (valor) => (valor === null || valor === undefined || valor === '' ? null : Math.round(Number(valor) * 10) / 10);
  const porNome = (nome) => secao(nome).map((linha) => ({ nome: linha.Nome, faltas: num(linha.Faltas), pacientes: num(linha.Pacientes) }));

  return ok({
    periodo: { de: meta.de, ate: meta.ate, anterior: meta.anterior, inicioCiclo: meta.inicio, hoje: meta.hoje },
    faltas: {
      porDia: secao('dia')
        .map((linha) => ({ dia: dataIso(linha.Dia), faltas: num(linha.Faltas) }))
        .sort((a, b) => a.dia.localeCompare(b.dia)),
      anterior: { faltas: num(anterior.Faltas), pacientes: num(anterior.Pacientes), reincidentes: num(anterior.Reincidentes) },
      calor: secao('calor').map((linha) => ({ dia: num(linha.DiaSemana), hora: num(linha.Hora), faltas: num(linha.Faltas) })),
      porNumero: secao('numeroFalta')
        .map((linha) => ({ numero: num(linha.Numero), faltas: num(linha.Faltas) }))
        .sort((a, b) => a.numero - b.numero),
      maiorFaltaRegra,
      porLocal: porNome('local'),
      porEspecialidade: porNome('especialidade')
    },
    acoes: {
      porMes: secao('acaoMes')
        .map((linha) => ({ mes: linha.Mes, tipo: linha.Tipo, quantidade: num(linha.Quantidade) }))
        .sort((a, b) => a.mes.localeCompare(b.mes)),
      resumo: {
        bloqueios: num(acao.Bloqueios),
        liberacoes: num(acao.Liberacoes),
        antecipadas: num(acao.Antecipadas),
        falhas: num(acao.Falhas),
        diasBloqueado: media(acao.DiasBloqueado),
        diasPoupados: media(acao.DiasPoupados)
      },
      porUsuario: secao('acaoUsuario').map((linha) => ({
        usuario: linha.Usuario,
        bloqueios: num(linha.Bloqueios),
        liberacoes: num(linha.Liberacoes),
        total: num(linha.Total)
      }))
    },
    solicitacoes: {
      porStatus: Object.fromEntries(secao('solStatus').map((linha) => [linha.Status, num(linha.Quantidade)])),
      porDia: secao('solDia')
        .map((linha) => ({ dia: dataIso(linha.Dia), quantidade: num(linha.Quantidade) }))
        .sort((a, b) => a.dia.localeCompare(b.dia)),
      tempo: {
        minutosResposta: media(tempo.MinutosResposta),
        minutosLiberar: media(tempo.MinutosLiberar),
        aprovadas: num(tempo.Aprovadas),
        recusadas: num(tempo.Recusadas),
        total: num(tempo.Total)
      },
      porSolicitante: secao('solSolicitante').map((linha) => ({
        usuario: linha.SolicitadoPor,
        quantidade: num(linha.Quantidade),
        aprovadas: num(linha.Aprovadas)
      }))
    }
  });
}

if (meta.action === 'acoes') {
  const contagem = secao('contagem')[0] || {};

  return ok({
    page: meta.page,
    pageSize: meta.pageSize,
    total: num(contagem.Total),
    contagem: {
      bloqueios: num(contagem.Bloqueios),
      liberacoes: num(contagem.Liberacoes),
      antecipadas: num(contagem.Antecipadas),
      falhas: num(contagem.Falhas)
    },
    usuarios: secao('usuario').map((linha) => linha.Usuario),
    items: secao('acao').map((acao) => ({
      id: acao.Id,
      idPaciente: num(acao.IdPaciente),
      nome: acao.NomePaciente || null,
      acao: acao.Acao,
      origem: acao.Origem,
      usuario: acao.Usuario,
      motivo: acao.Motivo,
      idAgenda: acao.IdAgendaReferencia,
      numeroFalta: acao.NumeroFalta,
      dataFimBloqueio: dataIso(acao.DataFimBloqueio),
      antecipada: bool(acao.Antecipada),
      sucesso: bool(acao.Sucesso),
      httpStatus: acao.HttpStatus,
      respostaApi: acao.RespostaApi,
      execucao: acao.IdExecucaoN8n,
      idSolicitacao: acao.IdSolicitacao ?? null,
      em: iso(acao.CriadoEm)
    }))
  });
}

if (meta.action === 'parametros') {
  const status = secao('status')[0] || {};

  return ok({
    regra: {
      prazosDias: REGRA.prazosDias,
      maiorFalta: maiorFaltaRegra,
      cicloInicio: REGRA.cicloInicio,
      fuso: REGRA.fuso,
      horarioBloqueio: REGRA.horarioBloqueio,
      liberacaoAutomatica: REGRA.liberacaoAutomatica,
      horarioLiberacao: REGRA.horarioLiberacao
    },
    ciclo: { inicio: meta.inicio, hoje: meta.hoje },
    status: {
      ultimaColeta: iso(status.UltimaColeta),
      ultimoBloqueioAutomatico: iso(status.UltimoBloqueioAutomatico),
      ultimaLiberacaoAutomatica: iso(status.UltimaLiberacaoAutomatica),
      ultimaAcaoPainel: iso(status.UltimaAcaoPainel),
      linhasControle: num(status.LinhasControle),
      linhasFaltas: num(status.LinhasFaltas)
    },
    cadastros: secao('cadastro')
      .map((linha) => ({ tipo: linha.Tipo, quantidade: num(linha.Quantidade), atualizadoEm: iso(linha.AtualizadoEm) }))
      .sort((a, b) => String(a.tipo).localeCompare(String(b.tipo)))
  });
}

return [{ json: { statusCode: 400, response: { error: 'Ação desconhecida.' } } }];
